export const CMS_CODES: readonly string[] = ['steel40', 'steel80', 'trade1200', 'trade3000', 'transit150', 'transit400', 'happy70', 'happy80', 'techC6', 'ct_steel60', 'ct_fuel80'];   // D045：委託碼（＝rules/commission.ts 表的順序，只往後加）
